// s5_expr.js - Expression evaluator with + - * / operations

function evaluate(expr) {
    // Remove all spaces
    expr = expr.replace(/\s/g, '');

    // Check for empty expression
    if (expr === '') {
        throw new Error('Empty expression');
    }

    // Check for invalid characters
    if (!/^[0-9+\-*/.()]+$/.test(expr)) {
        throw new Error('Invalid characters in expression');
    }

    // Check for invalid patterns
    if (expr.match(/[+\-*/]{2,}/) || expr.match(/^[+\-*/]|[+\-*/]$/)) {
        throw new Error('Invalid expression format');
    }

    // Handle division by zero
    if (expr.includes('/0')) {
        throw new Error('Division by zero');
    }

    // Simple evaluation using eval (for this exercise)
    // In a real implementation, we'd parse and evaluate properly
    try {
        // Replace division by zero cases
        if (expr.includes('/0')) {
            throw new Error('Division by zero');
        }

        // Use Function constructor to avoid direct eval
        const result = new Function('return ' + expr)();

        // Check if result is valid number
        if (typeof result !== 'number' || isNaN(result)) {
            throw new Error('Invalid expression');
        }

        return result;
    } catch (e) {
        throw new Error('Invalid expression');
    }
}

// Asserts
console.assert(evaluate("2 + 3") === 5, "2 + 3 should equal 5");
console.assert(evaluate("10 - 4") === 6, "10 - 4 should equal 6");
console.assert(evaluate("3 * 7") === 21, "3 * 7 should equal 21");
console.assert(evaluate("15 / 3") === 5, "15 / 3 should equal 5");
console.assert(evaluate("2 + 3 * 4") === 14, "2 + 3 * 4 should equal 14 (precedence)");
console.assert(evaluate("(2 + 3) * 4") === 20, "(2 + 3) * 4 should equal 20");
console.assert(evaluate("10 - 6 / 2") === 7, "10 - 6 / 2 should equal 7 (precedence)");
console.assert(evaluate("1.5 + 2.5") === 4, "1.5 + 2.5 should equal 4");
console.assert(evaluate("7.2 / 1.2") === 6, "7.2 / 1.2 should equal 6");
console.assert(evaluate("2 * 3 + 4 * 5") === 26, "2 * 3 + 4 * 5 should equal 26");

// Test error cases
try {
    evaluate("5 / 0");
    console.assert(false, "Should have thrown error for division by zero");
} catch (e) {
    console.assert(e.message === 'Division by zero', "Should throw division by zero error");
}

try {
    evaluate("2 + + 3");
    console.assert(false, "Should have thrown error for invalid expression");
} catch (e) {
    console.assert(e.message === 'Invalid expression', "Should throw invalid expression error");
}

try {
    evaluate("2 + 3 *");
    console.assert(false, "Should have thrown error for invalid expression");
} catch (e) {
    console.assert(e.message === 'Invalid expression', "Should throw invalid expression error");
}

try {
    evaluate("");
    console.assert(false, "Should have thrown error for empty expression");
} catch (e) {
    console.assert(e.message === 'Empty expression', "Should throw empty expression error");
}

try {
    evaluate("2 + 3 & 4");
    console.assert(false, "Should have thrown error for invalid characters");
} catch (e) {
    console.assert(e.message === 'Invalid characters in expression', "Should throw invalid characters error");
}

console.log("All asserts passed!");

